with d as (select value r from jsonb_array_elements($q$[{"notes":["Make the jalebi syrup and batter the day before if you like, this takes the stress out of frying day. Keep both in airtight containers at room temperature.","The garlic chutney keeps in the fridge for up to 3 days.","Fafda is best eaten warm and fresh, but jalebi will keep in the syrup for up to 2 days."],"steps":[{"text":"Make the jalebi syrup first: In a heavy-bottomed saucepan, combine the caster sugar and 300 ml water. Bring to a boil, stirring until the sugar dissolves completely. Add the lemon juice and crushed cardamom pods. If using saffron, crumble it into the syrup. Simmer for 10 minutes until the syrup thickens slightly and coats the back of a spoon. Set aside to cool completely."},{"text":"Make the jalebi batter: In a bowl, whisk together the plain flour and bicarbonate of soda. Add the yoghurt and water, stirring until you have a smooth, lump-free batter with a consistency like double cream, thin enough to flow through a piping bag, but not watery. If using saffron, crumble it into the batter. Stir in the 2 tbsp of neutral oil. Set aside for 15 minutes to rest."},{"text":"Make the garlic chutney: Blend all the ingredients together in a food processor or with a mortar and pestle until you reach a smooth paste. Transfer to a small bowl and set aside."},{"text":"Make the fafda batter: In a large bowl, whisk together the gram flour, yoghurt, salt, turmeric and cumin. Add the chopped green chilli. Gradually add the 200 ml water, stirring until you have a thick, smooth batter, it should be slightly thicker than the jalebi batter, dropping slowly from a spoon. Gently fold in the carrot, peas and red onion. Let the batter rest for 10 minutes."},{"text":"Heat the 1 litre of neutral oil in a heavy-bottomed, deep saucepan or wok to 170°C. You can check the temperature with a thermometer; if you don't have one, a small piece of batter should sizzle gently and brown in about 60 seconds."},{"text":"Fry the jalebi: Transfer the jalebi batter to a piping bag fitted with a thin nozzle (about 5 mm). Carefully squeeze the batter into the hot oil in spiral shapes, starting from the centre and spiralling outward, making each jalebi about 5 cm across. Fry 3–4 at a time so they don't touch. Fry for about 90 seconds until deep golden and crisp, then turn gently and fry the other side for another 30–45 seconds. Remove with a slotted spoon and immediately place in the cool jalebi syrup. Repeat until all the batter is used. Set the jalebi aside in the syrup."},{"text":"Fry the fafda: Once the oil returns to 170°C, carefully lower a fafda mould (or use a kitchen spoon or ladle) into the oil if you have one. Alternatively, use your hands or two spoons to shape the batter into loose, irregular nests about 10 cm across, don't make them perfectly compact; fafda should be airy and crispy. Fry 2–3 at a time for 3–4 minutes, turning halfway, until golden and crispy all over. The edges should be lacy and crackly. Remove with a slotted spoon and drain on paper towel."},{"text":"Serve the fafda warm with a jalebi on the side, a spoonful of garlic chutney, and a small bowl of the syrup for dipping."}],"id":"b2e46c60-cf60-41db-99ff-5f4de83ba0d2"},{"notes":["Make the wors up to 2 days ahead and store in the fridge. They freeze beautifully too.","If you don't have natural casings, make pattie wors instead: shape the mixture into thick patties and braai or pan-fry them.","Pap reheats well, if it thickens too much overnight, loosen it with a splash of water or milk on the stove.","Food safety: Cook mince, sausages, meatballs and liver right through to 75°C, with no pink in the centre."],"id":"434c23a8-59af-4d37-a327-3fde109af852"},{"notes":["Make it a day ahead: flavour deepens overnight. Reheat gently on the stove with a splash of water if needed.","For deeper colour and flavour, fry the paste longer in step 2, dark brown is better than light.","Serve with steamed white rice or fragrant jasmine rice to soak up the sauce.","Food safety: Cook chicken and other poultry until the juices run clear and the thickest part reaches 75°C."],"steps":[{"text":"Blend the shallots, garlic, ginger, galangal and dried chillies with 100 ml water until smooth. This is your rendang paste."},{"text":"Heat the oil in a large, heavy-based pot over medium heat. Add the paste and caraway seeds. Fry, stirring often, until fragrant and the oil begins to separate from the paste, about 8 minutes."},{"text":"Add the chicken pieces and stir to coat well in the paste. Cook for 5 minutes, stirring, until the chicken is sealed."},{"text":"Pour in the coconut milk and stir. Add the turmeric, lime leaves and a pinch of salt. Bring to a gentle simmer until the sauce is bubbling lightly and fragrant."},{"text":"Reduce heat to low. Simmer uncovered for 60 minutes, stirring every 10 minutes or so. The sauce will gradually reduce and thicken, and the oil will begin to separate again, this is what you want."},{"text":"Keep simmering until the sauce is thick, glossy and coats the chicken, and the chicken is very tender. Taste and adjust the salt. Serve with rice."}],"id":"1ec8f967-bbeb-4b34-939a-9d910417d33b"},{"notes":["Use the freshest white fish and seafood you can find, suquet is a stew that lets them shine.","The sofregit is the soul of this dish. Those 20 minutes of slow cooking transform the onions into something deep and essential.","Serve with aioli or toum on the side if you like, a dollop in each bowl is very Catalan.","Food safety: Cook fish until it turns opaque and flakes easily, about 63°C in the thickest part. Cook mussels, clams and pipis only if they are alive and tightly closed (or close when tapped), and discard any that stay shut after cooking. Cook prawns until pink and opaque."],"steps":[{"text":"Heat the olive oil in a large, heavy-bottomed pot or cazuela over a low-medium heat. Add the sliced onions and cook, stirring often, for 15 to 20 minutes until very soft and golden. This is the sofregit, don't rush it. The onions should be almost jammy. Add the garlic and cook for another 2 minutes until fragrant."},{"text":"Stir in the crushed tomatoes and paprika. Cook gently for 5 minutes, letting the tomato meld with the sofregit base."},{"text":"Add the potatoes and fish stock. Bring to a simmer and cook for 12 to 15 minutes until the potatoes are almost tender."},{"text":"Add the white fish chunks and mussels. Simmer gently for 4 minutes, then add the prawns. Cook for another 3 to 4 minutes until the fish is just opaque and cooked through, the mussels have opened, and the prawns are pink."},{"text":"Discard any mussels that haven't opened. Taste and season with salt and black pepper."},{"text":"Ladle into bowls and scatter with fresh parsley. Serve with crusty bread to soak up the broth."}],"id":"d595ff1e-4fde-4539-8b54-507bcaf9e69a"},{"notes":["Make niter kibbeh at home: melt 200g butter over low heat, add 1 tsp fenugreek seeds, ½ tsp cardamom pods, 2 cloves, 1 bay leaf and a pinch of ground turmeric. Let it infuse for 10 minutes, then strain through muslin into a jar and refrigerate.","Doro wat keeps well: store in the fridge for up to 3 days and reheat gently with a splash of water if needed.","For a thinner sauce, add more water and simmer a few minutes longer. Selam likes her stew thick enough to sit on the injera without running.","Food safety: Cook chicken and other poultry until the juices run clear and the thickest part reaches 75°C. Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"id":"03ee7fb1-ed47-4dce-b19a-fd2f4d693809"},{"notes":["Make these a day ahead and refrigerate, they taste better when the flavours have settled. Bring to room temperature before serving.","If you can't find Aleppo pepper, use a mix of smoked paprika and a pinch of chilli flakes."],"id":"15333b27-52e1-4750-a6bd-ac4758ccd7e0"},{"notes":["Milkfish can be bony: eat slowly and you'll find most of the small bones soften in the vinegar. If you can't find it, use any firm white fish about the same size, barramundi or snapper work well.","Make ahead: braise to completion, cool in the liquid, and refrigerate for up to 3 days. Reheat gently over low heat, covered."],"id":"051076a2-31a0-4c94-ba01-b7e95c8140fb"},{"notes":["Very fresh sardines are essential here. If you can't find them, use fresh anchovies (alici) instead.","The pasta water is crucial, it helps emulsify the oil and coat the spaghetti properly."],"id":"e57baa31-6036-4dfa-8602-2b22cf208820"},{"notes":["Food safety: Cook fish until it turns opaque and flakes easily, about 63°C in the thickest part."],"steps":[{"text":"Heat the oven to 200°C, then arrange the fish fillets, skin side down, in a baking dish large enough to hold them in a single layer. Season with salt and pepper."},{"text":"Scatter the sliced brown onion over the fish. Pour the coconut cream and water around the fish, then squeeze the juice from the lime halves over the top. Season again lightly with salt and pepper. Cook until the fish is opaque and flakes easily and the onion is soft."},{"text":"Bake, uncovered, for 25–30 minutes, until the fish is cooked through and flakes easily when tested with a fork."},{"text":"Scatter the chopped spring onion over the top and serve hot with the coconut broth spooned over. Serve with steamed rice and pickled onions on the side."}],"id":"25e4e0ed-4767-4b4c-a914-cfec4f89a438"},{"notes":["Swap the carrot for peas, corn, or any cooked veg you have left over.","If you've got leftover cooked chicken, use 400 g and add it after the garlic and ginger, just heat through before the soy mixture.","Food safety: Cook chicken and other poultry until the juices run clear and the thickest part reaches 75°C. Cook mince and sausages until no pink remains and the centre reaches 75°C."],"id":"b19933fd-b090-41d2-a252-838c11cc03f2"},{"notes":["This recipe uses cooked chicken for safe home cooking. Traditional lawar is made with raw poultry only when the cook has direct knowledge of the animal's health and handling.","Make base genep fresh if you can: blend together 4 shallots, 3 garlic cloves, 1 tbsp ginger, 1 tsp galangal, 1 tsp ground turmeric, 2–3 red chillies and 1 tbsp coconut oil.","Lawar is best served the same day it's made, on banana leaf if you have it.","Cook chicken until it reaches 75°C in the thickest part and the juices run clear."],"id":"f79bc613-8077-4b60-8553-dacc295ca773"},{"notes":["This gulai keeps well in the fridge for up to 3 days and tastes even better the next day as the spices settle.","Freeze it in portions, it thaws and reheats beautifully.","Use 2 dried chillies for mild heat, 4 for proper burn; it depends on the family eating it that night."],"steps":[{"text":"Soak the dried chillies in hot water for 5 minutes until soft, then drain."},{"text":"Grind the soaked chillies, shallot, garlic, ginger, turmeric and cumin seeds to a paste using a mortar and pestle or spice grinder, adding a little water if needed."},{"text":"Heat the oil in a large pot or wok over medium heat. Fry the paste for 2 to 3 minutes, stirring constantly, until fragrant and darkened slightly."},{"text":"Add the cassava chunks and stir to coat with the paste, about 2 minutes."},{"text":"Pour in the coconut milk and water. Bring to a simmer, then reduce heat to medium-low until the sauce is just bubbling at the edges."},{"text":"Cook, uncovered, for 20 to 25 minutes, stirring occasionally, until the cassava is completely tender and the sauce has thickened slightly. The cassava should break apart easily when tested with a fork."},{"text":"Add the fish sauce and taste. Adjust salt and heat to your preference, remembering the chillies will have released their full flavour by now."},{"text":"Simmer for another minute, until the sauce is thick and glossy and the cassava is tender, then serve hot with steamed rice."}],"id":"915cfa45-ea0b-4e0e-9edd-97d31728cd02"},{"notes":["Make this a day ahead, it reheats beautifully and tastes even better the next day.","Serve with egg noodles, boiled potatoes, or just good bread for soaking up the gravy.","Food safety: Slow-cooked meat is safe once it is tender and the centre has reached at least 75°C."],"steps":[{"text":"Heat the oven to 160°C. Pat the brisket dry with paper towels and season generously on both sides with salt and pepper."},{"text":"Heat the oil in a large heavy-based pot or Dutch oven over medium-high heat. Working in batches if needed, brown the brisket on all sides until deep golden, about 3 minutes per side. Set the meat aside."},{"text":"Add the sliced onions to the pot and cook, stirring, until they start to soften and caramelize, about 5 minutes. They don't need to be fully cooked, they'll finish in the oven."},{"text":"Pour in the beef stock, scraping up any browned bits from the bottom of the pot. Return the brisket to the pot, nestling it into the onions. Add the bay leaves."},{"text":"Cover the pot with a lid and transfer to the oven. Braise for about 3 hours, until the brisket is fork-tender and the meat shreds easily."},{"text":"Remove from the oven and let the brisket rest in the braising liquid for 10 minutes. Slice against the grain and serve with the soft onions and braising liquid spooned over the top."}],"id":"cb6423c3-4b0e-4589-9c60-bb8ccf0a4f7a"},{"notes":["Serve with rice, cornbread, or just a spoon and good company.","Tastes even better the next day, the flavours deepen as it sits."],"steps":[{"text":"Heat your cast iron over medium-high heat. Brown the andouille slices, 3–4 minutes per side, until they've got a nice colour. Transfer to a plate."},{"text":"Add the oil to the same pan. Sauté the onion until it's soft and golden, about 5 minutes. Stir in the garlic and cook for 1 minute until fragrant."},{"text":"Add the okra and cook, stirring occasionally, for about 8 minutes. Don't fuss with it too much, you want it to brown slightly."},{"text":"Pour in the crushed tomatoes and their juice, then add the corn and chicken stock. Bring to a simmer until the stew is bubbling gently and starting to thicken."},{"text":"Return the sausage to the pan. Reduce heat to medium-low and simmer, uncovered, for 15–20 minutes, stirring gently now and then, until the okra is tender and the flavours have married."},{"text":"Taste and season with salt and pepper. Serve warm."}],"id":"f67d9140-3276-4ef4-af80-d4750017c173"},{"notes":["Rohan likes his pelau hot; remove the green chillies before serving if your household prefers it milder.","Leftover pelau keeps in the fridge for 3 days and reheats beautifully on the stove with a splash of water.","You can swap the chicken for beef chuck or lamb shoulder for a different flavour, both work beautifully and need the full cooking time.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"steps":[{"text":"Heat the oil in a large, heavy-bottomed pot over medium heat. Sprinkle the caster sugar evenly across the base and let it sit without stirring for 2 to 3 minutes. Once it starts to brown at the edges, stir constantly until it's a deep golden brown, almost black, this is the burnt sugar that gives pelau its dark gravy, about 5 to 6 minutes total. It'll smell slightly burnt; that's right."},{"text":"Working quickly, add the chicken pieces to the burnt sugar, stirring constantly to coat them. They'll sizzle and stick a little, that's fine. Cook, stirring, for 3 to 4 minutes until the chicken is sealed on the outside."},{"text":"Add the sliced onions and stir well, scraping up any stuck bits from the bottom of the pot. Cook for 5 to 6 minutes until the onions soften and start to caramelise."},{"text":"Stir in the garlic, ginger and green chillies, and cook for 1 minute until fragrant. Add the ground cumin and ground coriander, stir, and cook for another minute."},{"text":"Add the tomato paste and stir through, coating everything for about 1 minute. Pour in the coconut milk and chicken stock, stirring to loosen any stuck bits. Add the thyme sprigs."},{"text":"Bring to a boil, then reduce the heat to low. Cover and simmer for 15 to 20 minutes until the chicken is cooked through (75°C inside) and the liquid is starting to reduce."},{"text":"Stir in the rice and pigeon peas, mixing well so the rice is submerged. Season with salt and black pepper to taste. Cover and simmer over low heat for 20 to 25 minutes, stirring occasionally, until the rice is tender and has absorbed most of the liquid. If it looks dry but the rice isn't quite cooked, add a little more stock or water."},{"text":"Remove from heat, let it rest, covered, for 5 minutes. Fluff with a fork, sprinkle with fresh coriander, and serve with lime wedges on the side."}],"id":"6511e822-94f4-4660-91bc-a211cfeee277"}]$q$::jsonb)), up as (update public.published_recipes p set recipe = p.recipe || (d.r - 'id' - 'notes') || case when d.r ? 'notes' then jsonb_build_object('notes', coalesce((select jsonb_agg(n) from jsonb_array_elements(d.r->'notes') n where btrim(n#>>'{}') <> 'Food safety:'),'[]'::jsonb)) else '{}'::jsonb end, diets = case when d.r ? 'diets' then array(select jsonb_array_elements_text(d.r->'diets')) else p.diets end from d where p.id=(d.r->>'id')::uuid returning p.id) select (select count(*) from d) expected, (select count(*) from up) updated;